<?php
require __DIR__.'/includes/bootstrap.php';require_user();$ref=strtoupper(trim((string)($_GET['ref']??'')));$q=$pdo->prepare('SELECT g.booking_ref,g.journey_date,g.status AS group_status,t.train_name,t.train_code,sc.departure_time,sc.arrival_time,r.route_name,o.station_name AS origin_name,d.station_name AS destination_name FROM booking_groups g JOIN schedules sc ON sc.schedule_id=g.schedule_id JOIN trains t ON t.train_id=sc.train_id JOIN routes r ON r.route_id=sc.route_id JOIN stations o ON o.station_id=r.origin_station_id JOIN stations d ON d.station_id=r.destination_station_id WHERE g.booking_ref=? AND g.host_user_id=?');$q->execute([$ref,current_user()['user_id']]);$ticket=$q->fetch();$passengers=[];if($ticket){$q=$pdo->prepare('SELECT passenger_name,category,gender,seat_label,bogie_label,is_guest,status FROM bookings WHERE booking_group_id=(SELECT booking_group_id FROM booking_groups WHERE booking_ref=?) ORDER BY is_guest');$q->execute([$ref]);$passengers=$q->fetchAll();}$pageTitle='E-Ticket';require __DIR__.'/includes/header.php';?>
<?php if(!$ticket):?><section class="content"><h1>Ticket not found</h1><a href="<?=e(app_url('my-bookings.php'))?>">Return to bookings</a></section><?php else:?><section class="ticket-page"><div class="ticket"><h1>IIUC Railway E-Ticket</h1><div class="booking-id">Booking ID: #<?=e($ticket['booking_ref'])?></div><div class="ticket-grid"><div><?php foreach($passengers as $p):?><p><b><?=$p['is_guest']?'Guest':'Passenger'?>:</b> <?=e($p['passenger_name'])?></p><p><b>Category:</b> <?=e($p['category'])?></p><p><b>Gender:</b> <?=e($p['gender'])?></p><p><b>Seat:</b> <?=e($p['seat_label'])?></p><p><b>Bogie:</b> <?=e($p['bogie_label'])?></p><hr><?php endforeach?></div><div><p><b>Train:</b> <?=e($ticket['train_name'])?></p><p><b>Type:</b> <?=e($ticket['route_name'])?></p><p><b>Route:</b> <?=e($ticket['origin_name'])?> → <?=e($ticket['destination_name'])?></p><p><b>Journey Date:</b> <?=e($ticket['journey_date'])?></p><p><b>Departure:</b> <?=e(substr($ticket['departure_time'],0,5))?></p><p><b>Status:</b> <?=e($ticket['group_status'])?></p></div></div><div class="ticket-actions"><button class="button" onclick="window.print()">Print / Save ticket</button><a href="<?=e(app_url('my-bookings.php'))?>">My bookings</a></div></div></section><?php endif?>
<?php require __DIR__.'/includes/footer.php'; ?>
